INSERT INTO "public"."members" ("id", "name", "role", "intro", "image", "accent", "source", "sort_order", "created_at", "updated_at") VALUES ('alvaro', 'Alvaro', 'Buscador de peces grandes', 'Le van los retos, los embalses grandes y los montajes sobrios. Siempre busca una vuelta mas para sacar la captura del dia.', 'storage://team-assets/images/members/alvaro.jpeg', 'blue', 'seed', 3, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('dani', 'Dani', 'Movilidad y pesca de respuesta', 'Rapido para localizar actividad y muy resolutivo cuando toca cambiar de plan. Saca partido a charcas medias y escenarios tecnicos.', 'storage://team-assets/images/members/dani.jpeg', 'sand', 'seed', 2, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('juanma', 'Juanma', 'Estratega de largas sesiones', 'Paciente, muy fino con el montaje y siempre pendiente de la lectura del agua. Le gustan las sesiones largas y ajustar el cebo con mimo.', 'storage://team-assets/images/members/juanma.jpeg', 'teal', 'seed', 1, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('vima', 'Vima', 'Detalle, ritmo y constancia', 'Muy ordenado con los cebados y con mucha fe en los patrones repetibles. Cuando da con la clave, acumula capturas con regularidad.', 'storage://team-assets/images/members/vima.jpeg', 'green', 'seed', 4, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00');